test('real late Jide/Weiyu producer keeps every old room prefix before the three new rooms',async()=>{
 const {buildJideRearHall}=await import('../../src/scene/palace/special/JideRearHall.js');
 const source=fs.readFileSync(new URL('../../src/scene/zones/ZoneBase.js',import.meta.url),'utf8');
 const steps=source.slice(source.indexOf('*#buildSteps()'),source.indexOf('releaseConstructionReferences()'));
 const hall=source.slice(source.indexOf('  buildHall(item) {'),source.indexOf('  buildHallBaseline(item) {'));
 // Replay only the actual two relevant production call sites, not ZoneBase.
 // The static checks below bind this bounded order to the real wiring.
 const earlyBody=/return buildQiandongSecondFrontCourt\(this\.kit,item,this\.zoneJson\)/.test(hall);
 const lateCall='buildQiandongSecondFrontCourt(this.kit,items[59],this.zoneJson)';
 const lateBody=steps.includes(lateCall);
 const oldSeed=()=>({id:0,marker:'retained-pre-hook-room',floorY:0,doors:[],cover:[],spawns:[]});
 let original=new CourtKit(library(),'east-six');original.rooms.push(oldSeed());
 let expected;
 try{buildJideRearHall(original,'east-six');expected=structuredClone(original.rooms);assert.equal(expected.length,2);assert.equal(expected[1].sourceObjectId,'FC-59F7BB24CB')}
 finally{original.dispose(original.root);original=null}
 const candidate=new CourtKit(library(),'east-six'),seed=oldSeed();candidate.rooms.push(seed);
 try{
  if(earlyBody)api.buildQiandongSecondFrontCourt(candidate,data.items[59],data);
  buildJideRearHall(candidate,'east-six');
  const oldRefs=candidate.rooms.filter(r=>!r.sourceId?.startsWith('east-six/qiandong-second-front-court/'));
  const oldRecords=structuredClone(oldRefs);
  if(lateBody)api.buildQiandongSecondFrontCourt(candidate,data.items[59],data);
  assert.deepEqual(candidate.rooms.slice(0,expected.length),expected,'all old room records must keep their original array indices, including real Weiyu');
  for(let i=0;i<oldRefs.length;i++){assert.equal(candidate.rooms[i],oldRefs[i]);assert.deepEqual(oldRefs[i],oldRecords[i])}
  assert.equal(candidate.rooms[0],seed);
  assert.deepEqual(candidate.rooms.slice(expected.length).map(r=>r.sourceId),profile.QIANDONG_SECOND_FRONT_COURT.rooms.map(r=>`east-six/qiandong-second-front-court/${r.id}`));
  assert.equal(candidate.rooms.findIndex(r=>r.sourceObjectId==='FC-59F7BB24CB'),1);
  assert.equal(earlyBody,false,'item hall dispatch must not publish this deferred body');
  assert.ok(steps.includes("if(item.qiandongSecondFrontCourt!==undefined)break;"),'dedicated item is deferred rather than sent through generic hall');
  assert.ok(steps.indexOf(lateCall)>steps.indexOf('buildQianxingGlazedGate(this.kit,this.zoneJson)'));
  assert.ok(steps.indexOf(lateCall)>steps.indexOf('finalizeNingshouCoveredPlatforms(this.kit)'));
  assert.ok(steps.indexOf(lateCall)<steps.indexOf('this.kit.finish()'));
  assert.equal(source.match(/buildQiandongSecondFrontCourt\(this\.kit,/g)?.length,1,'exactly one body publication site');
  console.log('R271_LATE_ROOM_ORDER',JSON.stringify({baseline:expected.map((r,index)=>({index,id:r.id,sourceObjectId:r.sourceObjectId??null})),candidate:candidate.rooms.map((r,index)=>({index,id:r.id,sourceObjectId:r.sourceObjectId??null,sourceId:r.sourceId??null})),oldReferencesPreserved:true}));
 }finally{candidate.dispose(candidate.root)}
});

